# template is 3x3 directional stamp around 1 marker: overlay pattern with colors where non-background; do so
h,w=20,13
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
pat=[[5,5,None],[8,5,8],[8,5,0]]
g=[[4]*w for _ in range(h)]
for r,c in markers:
 for i in range(3):
  for j in range(3):
   if pat[i][j] is not None and 0<=r-1+i<h and 0<=c-1+j<w:
    g[r-1+i][c-1+j]=pat[i][j]
print('\n'.join(' '.join(map(str,x)) for x in g))
